// StrictServerInterface represents all server handlers.
type StrictServerInterface interface {
	// Healthz Liveness
	// (GET /healthz)
	Healthz(ctx context.Context, request HealthzRequestObject) (HealthzResponseObject, error)
	// Readyz Readiness (database reachable)
	// (GET /readyz)
	Readyz(ctx context.Context, request ReadyzRequestObject) (ReadyzResponseObject, error)
	// AcceptInvite Set the password with an invitation and open a session
	// (POST /v1/auth/invite/accept)
	AcceptInvite(ctx context.Context, request AcceptInviteRequestObject) (AcceptInviteResponseObject, error)
	// Login Exchange email and password for an access token and a refresh token
	// (POST /v1/auth/login)
	Login(ctx context.Context, request LoginRequestObject) (LoginResponseObject, error)
	// Logout Revoke the refresh token family of this session
	// (POST /v1/auth/logout)
	Logout(ctx context.Context, request LogoutRequestObject) (LogoutResponseObject, error)
	// RequestMagicLink Email a one time login link
	// (POST /v1/auth/magic-link)
	RequestMagicLink(ctx context.Context, request RequestMagicLinkRequestObject) (RequestMagicLinkResponseObject, error)
	// AcceptMagicLink Open a session with a magic link
	// (POST /v1/auth/magic-link/accept)
	AcceptMagicLink(ctx context.Context, request AcceptMagicLinkRequestObject) (AcceptMagicLinkResponseObject, error)
	// Refresh Rotate the refresh token and get a new access token
	// (POST /v1/auth/refresh)
	Refresh(ctx context.Context, request RefreshRequestObject) (RefreshResponseObject, error)
	// Register Create an account, its first tenant and the owner membership
	// (POST /v1/auth/register)
	Register(ctx context.Context, request RegisterRequestObject) (RegisterResponseObject, error)
	// ListInvoices Invoices of the active tenant, newest first
	// (GET /v1/documents/invoices)
	ListInvoices(ctx context.Context, request ListInvoicesRequestObject) (ListInvoicesResponseObject, error)
	// UploadInvoice Upload a supplier invoice (PDF or image)
	// (POST /v1/documents/invoices)
	UploadInvoice(ctx context.Context, request UploadInvoiceRequestObject) (UploadInvoiceResponseObject, error)
	// GetInvoice An invoice with every field's source and confidence
	// (GET /v1/documents/invoices/{invoiceId})
	GetInvoice(ctx context.Context, request GetInvoiceRequestObject) (GetInvoiceResponseObject, error)
	// ListExports What the client can download, with row counts
	// (GET /v1/exports)
	ListExports(ctx context.Context, request ListExportsRequestObject) (ListExportsResponseObject, error)
	// GetExport Download one export as CSV
	// (GET /v1/exports/{kind})
	GetExport(ctx context.Context, request GetExportRequestObject) (GetExportResponseObject, error)
	// ListAccounts Accounts of the active tenant
	// (GET /v1/ledger/accounts)
	ListAccounts(ctx context.Context, request ListAccountsRequestObject) (ListAccountsResponseObject, error)
	// CreateAccount Register a bank or Mercado Pago account (owner or operator)
	// (POST /v1/ledger/accounts)
	CreateAccount(ctx context.Context, request CreateAccountRequestObject) (CreateAccountResponseObject, error)
	// UploadStatement Upload a statement export of the account
	// (POST /v1/ledger/accounts/{accountId}/statements)
	UploadStatement(ctx context.Context, request UploadStatementRequestObject) (UploadStatementResponseObject, error)
	// ListFiles Statement files uploaded, accepted or quarantined, newest first
	// (GET /v1/ledger/files)
	ListFiles(ctx context.Context, request ListFilesRequestObject) (ListFilesResponseObject, error)
	// ListMovements Movements of one month, in date and line order
	// (GET /v1/ledger/movements)
	ListMovements(ctx context.Context, request ListMovementsRequestObject) (ListMovementsResponseObject, error)
	// ListQuarantine Files that did not enter, with the reason
	// (GET /v1/ledger/quarantine)
	ListQuarantine(ctx context.Context, request ListQuarantineRequestObject) (ListQuarantineResponseObject, error)
	// ListOpenItems Open items nothing settles yet, to link a movement by hand
	// (GET /v1/matching/items)
	ListOpenItems(ctx context.Context, request ListOpenItemsRequestObject) (ListOpenItemsResponseObject, error)
	// ListMatches Matches waiting in a tray
	// (GET /v1/matching/matches)
	ListMatches(ctx context.Context, request ListMatchesRequestObject) (ListMatchesResponseObject, error)
	// DecideMatch Decide on a match in the Suggested or Exceptions tray
	// (POST /v1/matching/matches/{matchId}/decision)
	DecideMatch(ctx context.Context, request DecideMatchRequestObject) (DecideMatchResponseObject, error)
	// DecideMovement Decide on a movement with no candidate (the client, then the operator)
	// (POST /v1/matching/movements/{movementId}/decision)
	DecideMovement(ctx context.Context, request DecideMovementRequestObject) (DecideMovementResponseObject, error)
	// ListPending Movements waiting for a person, from the latest run of each one
	// (GET /v1/matching/pending)
	ListPending(ctx context.Context, request ListPendingRequestObject) (ListPendingResponseObject, error)
	// RunMatching Run the matching engine over a month (owner or operator)
	// (POST /v1/matching/runs)
	RunMatching(ctx context.Context, request RunMatchingRequestObject) (RunMatchingResponseObject, error)
	// GetMe The caller, the active tenant and every membership
	// (GET /v1/me)
	GetMe(ctx context.Context, request GetMeRequestObject) (GetMeResponseObject, error)
	// GetMyTenant Onboarding status of the active tenant (portal home)
	// (GET /v1/me/tenant)
	GetMyTenant(ctx context.Context, request GetMyTenantRequestObject) (GetMyTenantResponseObject, error)
	// ListMetrics Results panel of the active tenant for a month
	// (GET /v1/metrics)
	ListMetrics(ctx context.Context, request ListMetricsRequestObject) (ListMetricsResponseObject, error)
	// ListMembers Members of the active tenant
	// (GET /v1/tenant/members)
	ListMembers(ctx context.Context, request ListMembersRequestObject) (ListMembersResponseObject, error)
	// AddMember Add a person to the active tenant (owner, or operator for the first owner)
	// (POST /v1/tenant/members)
	AddMember(ctx context.Context, request AddMemberRequestObject) (AddMemberResponseObject, error)
	// RemoveMember Remove a person from the active tenant (owner only)
	// (DELETE /v1/tenant/members/{userId})
	RemoveMember(ctx context.Context, request RemoveMemberRequestObject) (RemoveMemberResponseObject, error)
	// ListTenants Tenants where the caller is operator or accountant (operator console)
	// (GET /v1/tenants)
	ListTenants(ctx context.Context, request ListTenantsRequestObject) (ListTenantsResponseObject, error)
}

type StrictHandlerFunc func(ctx context.Context, w http.ResponseWriter, r *http.Request, request any) (any, error)
type StrictMiddlewareFunc func(f StrictHandlerFunc, operationID string) StrictHandlerFunc

type StrictHTTPServerOptions struct {
	RequestErrorHandlerFunc  func(w http.ResponseWriter, r *http.Request, err error)
	ResponseErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

func NewStrictHandler(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc) ServerInterface {
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: StrictHTTPServerOptions{
		RequestErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		},
		ResponseErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		},
	}}
}

func NewStrictHandlerWithOptions(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc, options StrictHTTPServerOptions) ServerInterface {
	if options.RequestErrorHandlerFunc == nil {
		options.RequestErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}
	if options.ResponseErrorHandlerFunc == nil {
		options.ResponseErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		}
	}
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: options}
}

type strictHandler struct {
	ssi         StrictServerInterface
	middlewares []StrictMiddlewareFunc
	options     StrictHTTPServerOptions
}

// Healthz operation middleware
func (sh *strictHandler) Healthz(w http.ResponseWriter, r *http.Request) {
	var request HealthzRequestObject

	handler := func(ctx context.Context, w http.ResponseWriter, r *http.Request, request interface{}) (interface{}, error) {
		return sh.ssi.Healthz(ctx, request.(HealthzRequestObject))
	}
	for _, middleware := range sh.middlewares {
		handler = middleware(handler, "Healthz")
	}

	response, err := handler(r.Context(), w, r, request)

	if err != nil {
		sh.options.ResponseErrorHandlerFunc(w, r, err)
	} else if validResponse, ok := response.(HealthzResponseObject); ok {
		if err := validResponse.VisitHealthzResponse(w); err != nil {
			sh.options.ResponseErrorHandlerFunc(w, r, err)
		}
	} else if response != nil {
		sh.options.ResponseErrorHandlerFunc(w, r, fmt.Errorf("unexpected response type: %T", response))
	}
}

